import React, { useState, useEffect } from 'react';
import { supabaseService } from '../../../services/supabaseService';
import { useToast } from '../../../contexts/ToastContext';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';
import Modal from '../../../components/ui/Modal';
import { formatLuc, formatNaira, lucToNaira } from '../../../utils/currencyUtils';

const InstructorWallet = ({ userId }) => {
    const { addToast } = useToast();
    const [earnings, setEarnings] = useState([]);
    const [balance, setBalance] = useState(0);
    const [lucWallet, setLucWallet] = useState({ balance: 0, total_earned: 0 });
    const [lucWithdrawals, setLucWithdrawals] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isPayoutModalOpen, setIsPayoutModalOpen] = useState(false);
    const [isLucWithdrawModalOpen, setIsLucWithdrawModalOpen] = useState(false);
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [payoutForm, setPayoutForm] = useState({
        bank_name: '',
        account_number: '',
        account_name: '',
        amount: ''
    });
    const [lucWithdrawForm, setLucWithdrawForm] = useState({
        amount: '',
        bank_name: '',
        account_number: '',
        account_name: ''
    });
    const [savedBankDetails, setSavedBankDetails] = useState({
        bank_name: '',
        account_number: '',
        account_name: ''
    });
    const [isEditingBank, setIsEditingBank] = useState(false);

    useEffect(() => {
        const saved = localStorage.getItem(`luc_bank_details_${userId}`);
        if (saved) {
            const parsed = JSON.parse(saved);
            setSavedBankDetails(parsed);
            setPayoutForm(prev => ({ ...prev, ...parsed }));
        }
        fetchWalletData();
    }, [userId]);

    const fetchWalletData = async () => {
        if (!userId) return;
        setIsLoading(true);
        try {
            const [balanceData, earningsData, lucData, lucTxns, lucWithdrawData] = await Promise.all([
                supabaseService.getInstructorBalance(userId),
                supabaseService.getInstructorEarnings(userId),
                supabaseService.getUserWallet(userId),
                supabaseService.getWalletTransactions(userId),
                supabaseService.getUserLucWithdrawals(userId)
            ]);
            
            setBalance(balanceData || 0);
            setEarnings(earningsData || []);
            setLucWallet(lucData);
            setLucWithdrawals(lucWithdrawData || []);
        } catch (error) {
            console.error('Failed to fetch wallet data:', error);
            addToast('Failed to load financial data', 'error');
        } finally {
            setIsLoading(false);
        }
    };

    const handleSaveBankDetails = (e) => {
        e.preventDefault();
        localStorage.setItem(`luc_bank_details_${userId}`, JSON.stringify(savedBankDetails));
        setPayoutForm(prev => ({ ...prev, ...savedBankDetails }));
        setLucWithdrawForm(prev => ({ ...prev, ...savedBankDetails }));
        setIsEditingBank(false);
        addToast('Bank details saved securely.', 'success');
    };

    const handlePayoutRequest = async (e) => {
        e.preventDefault();
        if (parseFloat(payoutForm.amount) < 20000) {
            addToast('Minimum payout threshold is ₦20,000', 'warning');
            return;
        }
        if (parseFloat(payoutForm.amount) > balance) {
            addToast('Insufficient balance', 'error');
            return;
        }

        try {
            await supabaseService.requestPayout(userId, {
                amount: payoutForm.amount,
                payout_method: {
                    type: 'bank',
                    bank: payoutForm.bank_name,
                    account: payoutForm.account_number,
                    name: payoutForm.account_name
                }
            });
            addToast('Payout request submitted successfully!', 'success');
            setIsPayoutModalOpen(false);
            setPayoutForm(prev => ({ ...prev, amount: '' }));
            fetchWalletData();
        } catch (error) {
            addToast('Failed to submit payout request', 'error');
        }
    };

    const handleLucWithdrawRequest = async (e) => {
        e.preventDefault();
        const amount = parseFloat(lucWithdrawForm.amount);
        
        if (amount < 100) {
            addToast('Minimum withdrawal is 100 LUC', 'warning');
            return;
        }
        if (amount > lucWallet.balance) {
            addToast('Insufficient LUC balance', 'error');
            return;
        }

        setIsSubmitting(true);
        try {
            await supabaseService.requestLucWithdrawal(userId, amount, {
                bank_name: lucWithdrawForm.bank_name,
                account_number: lucWithdrawForm.account_number,
                account_name: lucWithdrawForm.account_name
            });
            addToast('LUC withdrawal request submitted!', 'success');
            setIsLucWithdrawModalOpen(false);
            setLucWithdrawForm({ amount: '', bank_name: '', account_number: '', account_name: '' });
            fetchWalletData();
        } catch (error) {
            addToast('Failed to submit withdrawal request', 'error');
        } finally {
            setIsSubmitting(false);
        }
    };

    const totalGross = earnings.reduce((acc, curr) => acc + (curr.gross_amount || 0), 0);
    const totalNet = earnings.reduce((acc, curr) => acc + (curr.instructor_cut || 0), 0);
    const pendingLucWithdrawals = lucWithdrawals.filter(w => w.status === 'pending');

    return (
        <div className="space-y-8 animate-in fade-in duration-500">
            {/* LUC Credit Wallet */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="bg-gradient-to-br from-indigo-600 via-blue-600 to-cyan-500 rounded-[2.5rem] p-8 shadow-2xl relative overflow-hidden group">
                    <div className="absolute top-0 right-0 -mr-16 -mt-16 w-64 h-64 bg-white/10 rounded-full blur-3xl group-hover:scale-110 transition-transform duration-700" />
                    <div className="relative z-10">
                        <div className="flex items-center gap-3 mb-6">
                            <div className="w-10 h-10 rounded-2xl bg-white/20 flex items-center justify-center backdrop-blur-md">
                                <Icon name="Coins" size={20} className="text-white" />
                            </div>
                            <span className="text-white/80 font-bold uppercase tracking-widest text-xs">LUC Credits</span>
                        </div>
                        <div className="flex items-baseline gap-3">
                            <h3 className="text-4xl md:text-5xl font-black text-white tracking-tighter">
                                {formatAmount(lucWallet.balance)}
                            </h3>
                            <div className="flex flex-col">
                                <span className="text-lg font-bold text-white/70">LUC</span>
                                <span className="text-xs font-bold text-white/50">≈ {formatNaira(lucToNaira(lucWallet.balance))}</span>
                            </div>
                        </div>
                        <div className="mt-6 flex flex-wrap gap-3">
                            <Button 
                                onClick={() => setIsLucWithdrawModalOpen(true)}
                                className="bg-white text-indigo-600 hover:bg-white/90 border-none rounded-2xl px-6 font-bold shadow-lg"
                            >
                                Withdraw LUC
                            </Button>
                        </div>
                    </div>
                </div>

                <div className="bg-card border border-border rounded-[2.5rem] p-8 shadow-sm flex flex-col justify-between">
                    <div>
                        <div className="flex items-center gap-3 mb-4">
                            <div className="w-10 h-10 rounded-2xl bg-primary/10 flex items-center justify-center">
                                <Icon name="TrendingUp" size={20} className="text-primary" />
                            </div>
                            <span className="text-muted-foreground font-bold uppercase tracking-widest text-xs">LUC Lifetime Earnings</span>
                        </div>
                        <h3 className="text-3xl font-black text-foreground tracking-tighter">
                            {formatAmount(lucWallet.total_earned)} <span className="text-sm font-medium text-muted-foreground">LUC</span>
                        </h3>
                    </div>
                    {pendingLucWithdrawals.length > 0 && (
                        <div className="mt-4 p-3 bg-amber-500/10 border border-amber-500/20 rounded-xl">
                            <p className="text-xs text-amber-500 font-bold">
                                <Icon name="Clock" size={12} className="inline mr-1" />
                                {pendingLucWithdrawals.length} pending withdrawal(s)
                            </p>
                        </div>
                    )}
                </div>
            </div>

            {/* Naira Earnings Section */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className="bg-gradient-to-br from-slate-900 to-slate-950 border border-white/10 rounded-[2.5rem] p-8 shadow-2xl relative overflow-hidden group">
                    <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity">
                        <Icon name="Wallet" size={80} />
                    </div>
                    <p className="text-[10px] font-black uppercase tracking-widest text-slate-500 mb-2">Available Balance</p>
                    <h3 className="text-4xl font-black text-white italic">
                        ₦{balance.toLocaleString()}
                    </h3>
                    <Button 
                        variant="default" 
                        size="sm" 
                        className="mt-6 bg-secondary text-white hover:bg-secondary/80 font-black italic rounded-xl px-6 h-10"
                        onClick={() => setIsPayoutModalOpen(true)}
                        disabled={balance < 20000}
                    >
                        REQUEST PAYOUT
                    </Button>
                </div>

                <div className="bg-card border border-border rounded-[2.5rem] p-8 shadow-sm flex flex-col justify-between">
                    <div>
                        <p className="text-[10px] font-black uppercase tracking-widest text-muted-foreground mb-2">Total Gross Revenue</p>
                        <h3 className="text-2xl font-black text-primary italic">₦{totalGross.toLocaleString()}</h3>
                    </div>
                    <div className="mt-4 pt-4 border-t border-border flex items-center justify-between">
                        <span className="text-[10px] font-bold text-muted-foreground uppercase">Platform Fee (20%)</span>
                        <span className="text-xs font-black text-destructive italic">-₦{(totalGross * 0.2).toLocaleString()}</span>
                    </div>
                </div>

                <div className="bg-card border border-border rounded-[2.5rem] p-8 shadow-sm flex flex-col justify-between">
                    <div>
                        <p className="text-[10px] font-black uppercase tracking-widest text-muted-foreground mb-2">Net Instructor Earnings</p>
                        <h3 className="text-2xl font-black text-secondary italic">₦{totalNet.toLocaleString()}</h3>
                    </div>
                    <div className="mt-4 pt-4 border-t border-border flex items-center justify-between">
                        <span className="text-[10px] font-bold text-muted-foreground uppercase">Your Share (80%)</span>
                        <div className="flex items-center gap-1 text-secondary">
                            <Icon name="ArrowUpRight" size={12} />
                            <span className="text-xs font-black italic">ACTIVE</span>
                        </div>
                    </div>
                </div>
            </div>

            {/* Payout Configuration Section */}
            <div className="bg-card border border-border rounded-[2.5rem] overflow-hidden shadow-sm">
                <div className="p-8 border-b border-border flex items-center justify-between bg-muted/5">
                    <h4 className="text-lg font-black italic text-primary">Payout Configuration</h4>
                    <Button 
                        variant="ghost" 
                        size="sm" 
                        className="text-xs"
                        onClick={() => setIsEditingBank(!isEditingBank)}
                    >
                        {isEditingBank ? 'Cancel' : (savedBankDetails.account_number ? 'Update Details' : 'Add Bank')}
                    </Button>
                </div>
                <div className="p-8">
                    {isEditingBank ? (
                        <form onSubmit={handleSaveBankDetails} className="space-y-4 max-w-2xl">
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black uppercase tracking-widest text-muted-foreground ml-1">Bank Name</label>
                                    <input 
                                        type="text" 
                                        placeholder="e.g. GTBank"
                                        className="w-full h-12 bg-muted border border-border rounded-xl px-4 font-bold focus:ring-2 focus:ring-secondary outline-none transition-all"
                                        value={savedBankDetails.bank_name}
                                        onChange={(e) => setSavedBankDetails({...savedBankDetails, bank_name: e.target.value})}
                                        required
                                    />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black uppercase tracking-widest text-muted-foreground ml-1">Account Number</label>
                                    <input 
                                        type="text" 
                                        placeholder="0123456789"
                                        className="w-full h-12 bg-muted border border-border rounded-xl px-4 font-bold focus:ring-2 focus:ring-secondary outline-none transition-all"
                                        value={savedBankDetails.account_number}
                                        onChange={(e) => setSavedBankDetails({...savedBankDetails, account_number: e.target.value})}
                                        required
                                    />
                                </div>
                            </div>
                            <div className="space-y-2">
                                <label className="text-[10px] font-black uppercase tracking-widest text-muted-foreground ml-1">Account Holder Name</label>
                                <input 
                                    type="text" 
                                    placeholder="Your Full Name as it appears on account"
                                    className="w-full h-12 bg-muted border border-border rounded-xl px-4 font-bold focus:ring-2 focus:ring-secondary outline-none transition-all"
                                    value={savedBankDetails.account_name}
                                    onChange={(e) => setSavedBankDetails({...savedBankDetails, account_name: e.target.value})}
                                    required
                                />
                            </div>
                            <Button type="submit" variant="default" className="bg-secondary text-white font-black italic rounded-xl px-8 mt-4">
                                SAVE SECURELY
                            </Button>
                        </form>
                    ) : savedBankDetails.account_number ? (
                        <div className="flex items-center gap-6 p-6 border border-border rounded-2xl bg-muted/20">
                            <div className="w-16 h-16 rounded-full bg-secondary/10 flex items-center justify-center text-secondary">
                                <Icon name="Building" size={32} />
                            </div>
                            <div>
                                <h5 className="text-xl font-black text-primary italic uppercase">{savedBankDetails.bank_name}</h5>
                                <p className="text-sm font-bold text-slate-500 font-mono tracking-wider">{savedBankDetails.account_number}</p>
                                <p className="text-[10px] font-black uppercase tracking-widest text-muted-foreground mt-1">Beneficiary: <span className="text-primary">{savedBankDetails.account_name}</span></p>
                            </div>
                        </div>
                    ) : (
                        <div className="text-center py-8">
                            <Icon name="Landmark" size={48} className="mx-auto text-muted-foreground opacity-20 mb-4" />
                            <p className="text-sm text-muted-foreground font-medium italic">No payout method configured.</p>
                            <p className="text-xs text-muted-foreground mt-1">You must add your bank details before you can withdraw earnings.</p>
                        </div>
                    )}
                </div>
            </div>

            {/* Transaction Ledger */}
            <div className="bg-card border border-border rounded-[2.5rem] overflow-hidden shadow-sm">
                <div className="p-8 border-b border-border flex items-center justify-between bg-muted/5">
                    <h4 className="text-lg font-black italic text-primary">Revenue Ledger</h4>
                    <span className="text-[10px] font-black uppercase tracking-widest text-muted-foreground">Updated Real-Time</span>
                </div>
                
                {isLoading ? (
                    <div className="p-20 flex flex-col items-center justify-center space-y-4">
                        <div className="w-12 h-12 border-4 border-secondary border-t-transparent rounded-full animate-spin" />
                        <p className="text-xs font-bold text-slate-500 uppercase tracking-widest">Syncing Wallet...</p>
                    </div>
                ) : earnings.length > 0 ? (
                    <div className="overflow-x-auto">
                        <table className="w-full text-left border-collapse">
                            <thead>
                                <tr className="bg-muted/10">
                                    <th className="p-6 text-[10px] font-black uppercase tracking-widest text-muted-foreground">Date</th>
                                    <th className="p-6 text-[10px] font-black uppercase tracking-widest text-muted-foreground">Source</th>
                                    <th className="p-6 text-[10px] font-black uppercase tracking-widest text-muted-foreground">Gross</th>
                                    <th className="p-6 text-[10px] font-black uppercase tracking-widest text-muted-foreground">Your 80%</th>
                                    <th className="p-6 text-[10px] font-black uppercase tracking-widest text-muted-foreground">Status</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-border">
                                {earnings.map((tx) => (
                                    <tr key={tx.id} className="hover:bg-muted/5 transition-colors group">
                                        <td className="p-6 text-sm font-medium text-muted-foreground">
                                            {new Date(tx.created_at).toLocaleDateString()}
                                        </td>
                                        <td className="p-6">
                                            <p className="text-sm font-black text-primary italic uppercase tracking-tighter line-clamp-1">{tx.course_id || 'Platform Sale'}</p>
                                            <p className="text-[10px] text-muted-foreground uppercase font-bold">{tx.transaction_type}</p>
                                        </td>
                                        <td className="p-6 text-sm font-bold text-slate-500">₦{tx.gross_amount.toLocaleString()}</td>
                                        <td className="p-6 text-sm font-black text-secondary italic">₦{tx.instructor_cut.toLocaleString()}</td>
                                        <td className="p-6">
                                            <span className="px-2 py-1 rounded-full text-[9px] font-black bg-secondary/10 text-secondary border border-secondary/20 uppercase tracking-widest">
                                                {tx.status}
                                            </span>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                ) : (
                    <div className="p-20 text-center space-y-4">
                        <Icon name="Inbox" size={48} className="mx-auto text-muted-foreground opacity-20" />
                        <p className="text-sm text-muted-foreground font-medium italic">No transactions found in this cycle.</p>
                    </div>
                )}
            </div>

            {/* Naira Payout Modal */}
            <Modal
                isOpen={isPayoutModalOpen}
                onClose={() => setIsPayoutModalOpen(false)}
                title="Withdraw Funds"
                size="md"
            >
                <form onSubmit={handlePayoutRequest} className="space-y-6 p-2">
                    <div className="p-4 bg-secondary/5 border border-secondary/20 rounded-2xl">
                        <p className="text-xs text-secondary font-bold leading-relaxed">
                            Your 80% share will be processed via direct bank transfer. Ensure your account details are 100% accurate.
                        </p>
                    </div>

                    <div className="grid grid-cols-1 gap-4">
                        <div className="space-y-2">
                            <label className="text-[10px] font-black uppercase tracking-widest text-muted-foreground ml-1">Withdrawal Amount (Min ₦20,000)</label>
                            <input 
                                type="number" 
                                placeholder="0.00"
                                className="w-full h-14 bg-muted border border-border rounded-xl px-6 font-black italic focus:ring-2 focus:ring-secondary outline-none transition-all"
                                value={payoutForm.amount}
                                onChange={(e) => setPayoutForm({...payoutForm, amount: e.target.value})}
                                required
                            />
                        </div>
                        <div className="space-y-2">
                            <label className="text-[10px] font-black uppercase tracking-widest text-muted-foreground ml-1">Bank Name</label>
                            <input 
                                type="text" 
                                className="w-full h-14 bg-muted border border-border rounded-xl px-6 font-bold focus:ring-2 focus:ring-secondary outline-none transition-all opacity-70 cursor-not-allowed"
                                value={payoutForm.bank_name}
                                readOnly
                                title="Update this in your Payout Configuration"
                            />
                        </div>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div className="space-y-2">
                                <label className="text-[10px] font-black uppercase tracking-widest text-muted-foreground ml-1">Account Number</label>
                                <input 
                                    type="text" 
                                    className="w-full h-14 bg-muted border border-border rounded-xl px-6 font-bold focus:ring-2 focus:ring-secondary outline-none transition-all opacity-70 cursor-not-allowed"
                                    value={payoutForm.account_number}
                                    readOnly
                                />
                            </div>
                            <div className="space-y-2">
                                <label className="text-[10px] font-black uppercase tracking-widest text-muted-foreground ml-1">Account Holder Name</label>
                                <input 
                                    type="text" 
                                    className="w-full h-14 bg-muted border border-border rounded-xl px-6 font-bold focus:ring-2 focus:ring-secondary outline-none transition-all opacity-70 cursor-not-allowed"
                                    value={payoutForm.account_name}
                                    readOnly
                                />
                            </div>
                        </div>
                    </div>

                    <Button 
                        type="submit" 
                        fullWidth 
                        className="h-16 bg-secondary text-white font-black italic rounded-xl"
                    >
                        CONFIRM WITHDRAWAL
                    </Button>
                </form>
            </Modal>

            {/* LUC Withdrawal Modal */}
            <Modal
                isOpen={isLucWithdrawModalOpen}
                onClose={() => setIsLucWithdrawModalOpen(false)}
                title="Withdraw LUC Credits"
                size="md"
            >
                <form onSubmit={handleLucWithdrawRequest} className="space-y-6 p-2">
                    <div className="p-4 bg-indigo-500/5 border border-indigo-500/20 rounded-2xl">
                        <p className="text-xs text-indigo-500 font-bold leading-relaxed">
                            <Icon name="Info" size={12} className="inline mr-1" />
                            1 LUC = ₦10. Minimum withdrawal: 100 LUC (₦1,000). Requests are reviewed manually by admin.
                        </p>
                    </div>

                    <div className="space-y-2">
                        <label className="text-[10px] font-black uppercase tracking-widest text-muted-foreground ml-1">
                            Amount (LUC)
                        </label>
                        <input 
                            type="number" 
                            placeholder="e.g. 500"
                            min="100"
                            max={lucWallet.balance}
                            className="w-full h-14 bg-muted border border-border rounded-xl px-6 font-black italic focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
                            value={lucWithdrawForm.amount}
                            onChange={(e) => setLucWithdrawForm({...lucWithdrawForm, amount: e.target.value})}
                            required
                        />
                        <p className="text-[10px] text-muted-foreground ml-1">
                            ≈ {formatNaira(lucToNaira(parseFloat(lucWithdrawForm.amount) || 0))} | Available: {formatAmount(lucWallet.balance)} LUC
                        </p>
                    </div>

                    <div className="grid grid-cols-1 gap-4">
                        <div className="space-y-2">
                            <label className="text-[10px] font-black uppercase tracking-widest text-muted-foreground ml-1">Bank Name</label>
                            <input 
                                type="text" 
                                placeholder="e.g. GTBank"
                                className="w-full h-12 bg-muted border border-border rounded-xl px-4 font-bold focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
                                value={lucWithdrawForm.bank_name}
                                onChange={(e) => setLucWithdrawForm({...lucWithdrawForm, bank_name: e.target.value})}
                                required
                            />
                        </div>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div className="space-y-2">
                                <label className="text-[10px] font-black uppercase tracking-widest text-muted-foreground ml-1">Account Number</label>
                                <input 
                                    type="text" 
                                    placeholder="0123456789"
                                    className="w-full h-12 bg-muted border border-border rounded-xl px-4 font-bold focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
                                    value={lucWithdrawForm.account_number}
                                    onChange={(e) => setLucWithdrawForm({...lucWithdrawForm, account_number: e.target.value})}
                                    required
                                />
                            </div>
                            <div className="space-y-2">
                                <label className="text-[10px] font-black uppercase tracking-widest text-muted-foreground ml-1">Account Holder Name</label>
                                <input 
                                    type="text" 
                                    placeholder="Your full name"
                                    className="w-full h-12 bg-muted border border-border rounded-xl px-4 font-bold focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
                                    value={lucWithdrawForm.account_name}
                                    onChange={(e) => setLucWithdrawForm({...lucWithdrawForm, account_name: e.target.value})}
                                    required
                                />
                            </div>
                        </div>
                    </div>

                    <Button 
                        type="submit" 
                        fullWidth 
                        className="h-14 bg-indigo-600 hover:bg-indigo-700 text-white font-black italic rounded-xl"
                        isLoading={isSubmitting}
                    >
                        SUBMIT WITHDRAWAL REQUEST
                    </Button>
                </form>
            </Modal>
        </div>
    );

    function formatAmount(amount) {
        return new Intl.NumberFormat().format(amount);
    }
};

export default InstructorWallet;