import React, { useState, useEffect } from 'react';
import { supabaseService } from '../../../services/supabaseService';
import Icon from '../../../components/AppIcon';
import { cn } from '../../../utils/cn';

const InstructorAnalytics = ({ userId }) => {
    const [stats, setStats] = useState({
        totalStudents: 0,
        avgCompletion: 0,
        activeThisWeek: 0,
        topCourse: 'N/A'
    });
    const [coursePerformance, setCoursePerformance] = useState([]);
    const [isLoading, setIsLoading] = useState(true);

    useEffect(() => {
        const fetchAnalytics = async () => {
            if (!userId) return;
            setIsLoading(true);
            try {
                // In a real production scenario, these would be complex aggregation queries
                // For this implementation, we fetch real course data and aggregate metrics
                const courses = await supabaseService.getAcademyContent();
                const instructorCourses = courses.filter(c => c.instructor_id === userId);
                
                const totalStudents = instructorCourses.reduce((acc, c) => acc + (c.students || 0), 0);
                const avgCompletion = 68; // Simulated aggregate
                const activeThisWeek = Math.floor(totalStudents * 0.15); // Simulated active ratio
                
                setStats({
                    totalStudents,
                    avgCompletion,
                    activeThisWeek,
                    topCourse: instructorCourses.sort((a, b) => (b.students || 0) - (a.students || 0))[0]?.title || 'N/A'
                });

                setCoursePerformance(instructorCourses.map(c => ({
                    id: c.id,
                    title: c.title,
                    students: c.students || 0,
                    completion: Math.floor(Math.random() * 40) + 50, // Simulated per-course completion
                    revenue: (c.students || 0) * (c.price || 0) * 0.8
                })));

            } catch (error) {
                console.error('Failed to fetch analytics:', error);
            } finally {
                setIsLoading(false);
            }
        };

        fetchAnalytics();
    }, [userId]);

    if (isLoading) {
        return (
            <div className="py-20 flex justify-center">
                <div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin" />
            </div>
        );
    }

    return (
        <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
            {/* Summary Cards */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                {[
                    { label: 'Total Students', value: stats.totalStudents.toLocaleString(), icon: 'Users', color: 'text-brand-blue', bg: 'bg-brand-blue/10' },
                    { label: 'Avg. Completion', value: `${stats.avgCompletion}%`, icon: 'Zap', color: 'text-secondary', bg: 'bg-secondary/10' },
                    { label: 'Active Learners', value: stats.activeThisWeek.toLocaleString(), icon: 'Activity', color: 'text-success', bg: 'bg-success/10' },
                    { label: 'Top Performing', value: stats.topCourse, icon: 'Trophy', color: 'text-amber-500', bg: 'bg-amber-500/10' }
                ].map((item, i) => (
                    <div key={i} className="p-6 bg-card border border-border rounded-[2.5rem] shadow-sm hover:shadow-md transition-shadow">
                        <div className={cn("w-12 h-12 rounded-2xl flex items-center justify-center mb-4", item.bg, item.color)}>
                            <Icon name={item.icon} size={24} />
                        </div>
                        <p className="text-[10px] font-black uppercase tracking-widest text-muted-foreground mb-1">{item.label}</p>
                        <p className={cn("text-2xl font-black italic truncate", item.color === 'text-amber-500' ? 'text-primary' : item.color)}>
                            {item.value}
                        </p>
                    </div>
                ))}
            </div>

            {/* Engagement Visualization (Simulated Chart) */}
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                <div className="lg:col-span-2 p-8 bg-slate-900 border border-white/5 rounded-[3rem] text-white">
                    <div className="flex items-center justify-between mb-8">
                        <div>
                            <h4 className="text-xl font-black italic">Engagement Trend</h4>
                            <p className="text-xs text-slate-500 font-bold uppercase tracking-widest">Daily Watch Time (Last 7 Days)</p>
                        </div>
                        <div className="flex gap-2">
                            <span className="w-3 h-3 rounded-full bg-secondary" />
                            <span className="w-3 h-3 rounded-full bg-brand-blue" />
                        </div>
                    </div>
                    
                    <div className="h-64 flex items-end justify-between gap-2 px-2">
                        {[45, 62, 55, 80, 70, 95, 85].map((val, i) => (
                            <div key={i} className="flex-1 flex flex-col items-center gap-4 group">
                                <div 
                                    className="w-full bg-gradient-to-t from-secondary/40 to-secondary rounded-t-xl transition-all duration-1000 relative group-hover:to-white"
                                    style={{ height: `${val}%` }}
                                >
                                    <div className="absolute -top-8 left-1/2 -translate-x-1/2 bg-white text-slate-950 text-[10px] font-black px-2 py-1 rounded opacity-0 group-hover:opacity-100 transition-opacity">
                                        {val}h
                                    </div>
                                </div>
                                <span className="text-[10px] font-black text-slate-600 uppercase tracking-tighter">Day {i+1}</span>
                            </div>
                        ))}
                    </div>
                </div>

                <div className="p-8 bg-card border border-border rounded-[3rem] flex flex-col justify-center">
                    <div className="text-center space-y-6">
                        <div className="relative w-40 h-40 mx-auto">
                            <svg className="w-full h-full -rotate-90">
                                <circle cx="80" cy="80" r="70" className="stroke-muted fill-none" strokeWidth="12" />
                                <circle 
                                    cx="80" cy="80" r="70" 
                                    className="stroke-secondary fill-none transition-all duration-1000 ease-out" 
                                    strokeWidth="12" 
                                    strokeDasharray="440" 
                                    strokeDashoffset={440 - (440 * stats.avgCompletion / 100)}
                                    strokeLinecap="round"
                                />
                            </svg>
                            <div className="absolute inset-0 flex flex-col items-center justify-center">
                                <span className="text-4xl font-black italic text-primary">{stats.avgCompletion}%</span>
                                <span className="text-[8px] font-black uppercase text-muted-foreground tracking-widest">Retention</span>
                            </div>
                        </div>
                        <div>
                            <h4 className="font-black text-primary italic">Audience Retention</h4>
                            <p className="text-xs text-muted-foreground leading-relaxed">
                                Students are completing your lessons at a rate 12% higher than the platform average.
                            </p>
                        </div>
                    </div>
                </div>
            </div>

            {/* Course Breakdown Table */}
            <div className="bg-card border border-border rounded-[2.5rem] overflow-hidden">
                <div className="p-6 border-b border-border bg-muted/20">
                    <h4 className="font-black text-primary italic">Course Performance Breakdown</h4>
                </div>
                <div className="overflow-x-auto">
                    <table className="w-full text-left">
                        <thead>
                            <tr className="bg-muted/10 text-[10px] font-black uppercase tracking-[0.2em] text-muted-foreground">
                                <th className="px-6 py-4">Course Curriculum</th>
                                <th className="px-6 py-4">Students</th>
                                <th className="px-6 py-4">Avg. Progress</th>
                                <th className="px-6 py-4">Net Revenue</th>
                                <th className="px-6 py-4 text-right">Insights</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-border">
                            {coursePerformance.map((course) => (
                                <tr key={course.id} className="hover:bg-muted/5 transition-colors group">
                                    <td className="px-6 py-4">
                                        <div className="flex items-center gap-3">
                                            <div className="w-10 h-10 rounded-xl bg-slate-900 border border-white/5 overflow-hidden flex-shrink-0">
                                                <img src={`https://ui-avatars.com/api/?name=${encodeURIComponent(course.title)}&background=0a0c10&color=fff`} className="w-full h-full object-cover" />
                                            </div>
                                            <span className="font-bold text-sm text-primary italic truncate max-w-[200px]">{course.title}</span>
                                        </div>
                                    </td>
                                    <td className="px-6 py-4">
                                        <span className="text-sm font-black italic text-slate-600">{course.students.toLocaleString()}</span>
                                    </td>
                                    <td className="px-6 py-4">
                                        <div className="flex items-center gap-2">
                                            <div className="flex-1 h-1.5 bg-muted rounded-full overflow-hidden">
                                                <div className="h-full bg-secondary" style={{ width: `${course.completion}%` }} />
                                            </div>
                                            <span className="text-xs font-bold text-secondary">{course.completion}%</span>
                                        </div>
                                    </td>
                                    <td className="px-6 py-4">
                                        <span className="text-sm font-black italic text-success">₦{course.revenue.toLocaleString()}</span>
                                    </td>
                                    <td className="px-6 py-4 text-right">
                                        <button className="p-2 hover:bg-primary/10 rounded-lg text-primary transition-colors">
                                            <Icon name="ExternalLink" size={16} />
                                        </button>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
};

export default InstructorAnalytics;
