import React, { useState, useEffect } from 'react';
import { supabaseService } from '../../../services/supabaseService';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';
import Input from '../../../components/ui/Input';
import { cn } from '../../../utils/cn';
import { useToast } from '../../../contexts/ToastContext';

const BroadcastManager = ({ instructorId, courses = [] }) => {
    const { addToast } = useToast();
    const [announcements, setAnnouncements] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isCreating, setIsCreating] = useState(false);
    const [formData, setFormData] = useState({
        title: '',
        content: '',
        course_id: '', // Empty means 'All Students'
        type: 'info',
        is_critical: false
    });

    useEffect(() => {
        fetchAnnouncements();
    }, [instructorId]);

    const fetchAnnouncements = async () => {
        if (!instructorId) return;
        setIsLoading(true);
        try {
            const data = await supabaseService.getInstructorAnnouncements(instructorId);
            setAnnouncements(data);
        } catch (error) {
            console.error('Failed to fetch announcements:', error);
        } finally {
            setIsLoading(false);
        }
    };

    const handleCreate = async (e) => {
        e.preventDefault();
        if (!formData.title || !formData.content) {
            addToast('Please fill in both title and content.', 'warning');
            return;
        }

        setIsCreating(true);
        try {
            await supabaseService.createAnnouncement({
                ...formData,
                course_id: formData.course_id || null
            });
            addToast('Announcement broadcasted successfully!', 'success');
            setFormData({ title: '', content: '', course_id: '', type: 'info', is_critical: false });
            fetchAnnouncements();
        } catch (error) {
            console.error('Broadcast failed:', error);
            addToast('Failed to send broadcast.', 'error');
        } finally {
            setIsCreating(false);
        }
    };

    const handleDelete = async (id) => {
        if (!window.confirm('Are you sure you want to delete this announcement?')) return;
        try {
            await supabaseService.deleteAnnouncement(id);
            addToast('Announcement removed.', 'info');
            fetchAnnouncements();
        } catch (error) {
            addToast('Delete failed.', 'error');
        }
    };

    return (
        <div className="space-y-10 animate-in fade-in slide-in-from-bottom-4 duration-700">
            {/* Create Section */}
            <section className="bg-slate-900 border border-white/5 rounded-[3rem] p-8 md:p-12 text-white relative overflow-hidden">
                <div className="absolute top-0 right-0 w-64 h-64 bg-primary/10 rounded-full blur-[80px] pointer-events-none" />
                
                <div className="relative z-10 max-w-3xl">
                    <div className="flex items-center gap-4 mb-8">
                        <div className="w-12 h-12 rounded-2xl bg-primary/20 flex items-center justify-center text-primary">
                            <Icon name="Megaphone" size={24} />
                        </div>
                        <div>
                            <h3 className="text-2xl font-black italic tracking-tight">New Broadcast</h3>
                            <p className="text-xs text-slate-500 font-bold uppercase tracking-widest">Update your students in real-time</p>
                        </div>
                    </div>

                    <form onSubmit={handleCreate} className="space-y-6">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            <div className="space-y-2">
                                <label className="text-[10px] font-black uppercase tracking-widest text-slate-500 ml-1">Target Audience</label>
                                <select 
                                    className="w-full bg-white/5 border border-white/10 rounded-2xl px-4 py-3 text-sm font-bold italic focus:border-primary outline-none transition-all"
                                    value={formData.course_id}
                                    onChange={(e) => setFormData({ ...formData, course_id: e.target.value })}
                                >
                                    <option value="" className="bg-slate-900">All My Students</option>
                                    {courses.map(c => (
                                        <option key={c.id} value={c.id} className="bg-slate-900">{c.title}</option>
                                    ))}
                                </select>
                            </div>
                            <div className="space-y-2">
                                <label className="text-[10px] font-black uppercase tracking-widest text-slate-500 ml-1">Update Type</label>
                                <select 
                                    className="w-full bg-white/5 border border-white/10 rounded-2xl px-4 py-3 text-sm font-bold italic focus:border-primary outline-none transition-all"
                                    value={formData.type}
                                    onChange={(e) => setFormData({ ...formData, type: e.target.value })}
                                >
                                    <option value="info" className="bg-slate-900">General Info</option>
                                    <option value="update" className="bg-slate-900">Curriculum Update</option>
                                    <option value="alert" className="bg-slate-900">Important Alert</option>
                                    <option value="assignment" className="bg-slate-900">New Assignment</option>
                                </select>
                            </div>
                        </div>

                        <Input 
                            placeholder="Announcement Title (e.g. Weekend Workshop Schedule)" 
                            className="bg-white/5 border-white/10 text-white placeholder:text-slate-600"
                            value={formData.title}
                            onChange={(e) => setFormData({ ...formData, title: e.target.value })}
                        />

                        <textarea 
                            placeholder="Write your message here..." 
                            className="w-full min-h-[150px] bg-white/5 border border-white/10 rounded-[2rem] p-6 text-sm font-medium focus:border-primary outline-none transition-all resize-none text-white placeholder:text-slate-600"
                            value={formData.content}
                            onChange={(e) => setFormData({ ...formData, content: e.target.value })}
                        />

                        <div className="flex flex-col md:flex-row items-center justify-between gap-6">
                            <label className="flex items-center gap-3 cursor-pointer group">
                                <input 
                                    type="checkbox" 
                                    className="w-5 h-5 rounded-lg bg-white/5 border-white/10 checked:bg-secondary transition-all"
                                    checked={formData.is_critical}
                                    onChange={(e) => setFormData({ ...formData, is_critical: e.target.checked })}
                                />
                                <span className="text-sm font-bold italic text-slate-400 group-hover:text-white transition-colors">Mark as Critical (High Visibility)</span>
                            </label>

                            <Button 
                                type="submit" 
                                isLoading={isCreating}
                                className="w-full md:w-auto px-10 h-14 bg-primary hover:bg-white hover:text-primary text-white font-black italic rounded-2xl transition-all shadow-xl shadow-primary/20"
                                iconName="Send"
                            >
                                SEND BROADCAST
                            </Button>
                        </div>
                    </form>
                </div>
            </section>

            {/* History Section */}
            <section className="space-y-6">
                <div className="flex items-center justify-between px-2">
                    <h4 className="text-xl font-black text-primary italic">Broadcast History</h4>
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{announcements.length} Sent</span>
                </div>

                <div className="grid grid-cols-1 gap-4">
                    {announcements.map((ann) => (
                        <div key={ann.id} className="p-6 bg-card border border-border rounded-[2.5rem] flex flex-col md:flex-row md:items-center justify-between gap-6 group">
                            <div className="flex items-start gap-4">
                                <div className={cn(
                                    "w-12 h-12 rounded-2xl flex items-center justify-center shrink-0",
                                    ann.type === 'alert' ? "bg-destructive/10 text-destructive" : "bg-primary/10 text-primary"
                                )}>
                                    <Icon name={ann.type === 'alert' ? 'AlertTriangle' : 'Info'} size={20} />
                                </div>
                                <div className="space-y-1">
                                    <div className="flex items-center gap-2">
                                        <h5 className="font-bold text-primary italic underline underline-offset-4 decoration-primary/20">{ann.title}</h5>
                                        {ann.is_critical && (
                                            <span className="px-1.5 py-0.5 rounded-md bg-destructive text-white text-[8px] font-black uppercase tracking-tighter">Critical</span>
                                        )}
                                    </div>
                                    <p className="text-xs text-muted-foreground line-clamp-1 max-w-xl">{ann.content}</p>
                                    <div className="flex items-center gap-3 pt-1">
                                        <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">
                                            {ann.course_id ? courses.find(c => c.id === ann.course_id)?.title || 'Course Specific' : 'Global Broadcast'}
                                        </span>
                                        <span className="w-1 h-1 rounded-full bg-slate-300" />
                                        <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">
                                            {new Date(ann.created_at).toLocaleDateString()}
                                        </span>
                                    </div>
                                </div>
                            </div>
                            <Button 
                                variant="ghost" 
                                size="sm" 
                                className="h-10 text-destructive hover:bg-destructive/10 opacity-0 group-hover:opacity-100 transition-opacity"
                                iconName="Trash2"
                                onClick={() => handleDelete(ann.id)}
                            >
                                DELETE
                            </Button>
                        </div>
                    ))}
                    {announcements.length === 0 && !isLoading && (
                        <div className="py-20 text-center border-4 border-dashed border-border rounded-[3rem]">
                            <Icon name="Inbox" size={48} className="mx-auto text-muted-foreground opacity-10 mb-4" />
                            <p className="text-sm text-muted-foreground italic font-medium">No broadcasts sent yet.</p>
                        </div>
                    )}
                </div>
            </section>
        </div>
    );
};

export default BroadcastManager;
